#!/usr/bin/env bash
# Ecosystem verification for mcpp#685, mcpp#687 and the MSVC toolset selection,
# against the PUBLISHED mcpp and index, inside a SubOS sandbox with CN mirrors
# for xlings and mcpp.
#
#   B64=$(base64 -w0 .agents/docs/2026-09-24-toolchain-selection-verify.sh)
#   xlings subos new v924
#   xlings subos use v924 --sandbox --cmd \
#     "echo $B64 | base64 -d > /tmp/v.sh && MCPP_VERIFY_VERSION=2026.9.24.1 bash /tmp/v.sh"
#
# Run it once against the previous release first (MCPP_VERIFY_VERSION=2026.9.21.3):
# the sections marked CHANGE must fail there and pass on the new release; the
# sections marked GUARD must pass on both. The #687 recipe fix lives in the index
# (openxlings/xim-pkgindex#870), so its section is a GUARD for mcpp and holds for
# both releases once the index carries the fix.
#
# The MSVC toolset selection is Windows-only and is verified by the Windows CI
# jobs (e2e 760, e2e 239); this Linux sandbox lists it under NOT RUN.
#
# The sandbox shares the xlings data directory, so a published mcpp is addressed
# by its store path and exact version. Its $HOME content persists between runs of
# one SubOS, so every section clears its own probe directory first.
set -u

VER="${MCPP_VERIFY_VERSION:?set MCPP_VERIFY_VERSION}"
STORE="${MCPP_VERIFY_BIN:-$HOME/.xlings/data/xpkgs/xim-x-mcpp/$VER/bin/mcpp}"
LLVM="${MCPP_VERIFY_LLVM:-22.1.8}"

fails=0
skipped=""
fail()    { printf 'ASSERT-FAIL: %s\n' "$1"; fails=$((fails + 1)); }
ok()      { printf 'ok: %s\n' "$1"; }
section() { printf '\n== %s ==\n' "$1"; }
skip()    { printf 'NOT RUN: %s\n' "$1"; skipped="$skipped
  - $1"; }
unset XLINGS_ACTIVE_SUBOS

root="$HOME/verify-924"
rm -rf "$root"; mkdir -p "$root"

section "A. GUARD: the published mcpp answers for itself, with CN mirrors for xlings and mcpp"
if [ ! -x "$STORE" ]; then
    fail "no mcpp at $STORE"; printf '\nfails=%d (nothing else can run)\n' "$fails"; exit 1
fi
got=$("$STORE" --version 2>&1 | head -1)
case "$got" in *"$VER"*) ok "mcpp --version says $got" ;; *) fail "mcpp --version says '$got', expected $VER" ;; esac
if command -v xlings >/dev/null 2>&1; then
    xlings config --mirror CN >/dev/null 2>&1 && ok "xlings config --mirror CN" || fail "xlings config --mirror CN"
fi
"$STORE" self config --mirror CN >/dev/null 2>&1 && ok "mcpp self config --mirror CN" || fail "mcpp self config --mirror CN"
grep -q '"mirror": *"CN"' "$HOME/.mcpp/registry/.xlings.json" 2>/dev/null \
    && ok "mcpp's xlings reads mirror CN" || fail "mcpp's xlings does not read mirror CN"
timeout 900 "$STORE" index update > "$root/index-update.log" 2>&1 \
    && ok "mcpp index update" || { fail "mcpp index update"; tail -5 "$root/index-update.log"; }

section "B. GUARD: a new project builds and runs with the default toolchain"
d=$root/b; mkdir -p "$d"; cd "$d"
"$STORE" new hello > /dev/null 2>&1
cd hello
if timeout 1800 "$STORE" run > run.log 2>&1 && grep -q 'Hello' run.log; then
    ok "mcpp new + run"
else
    fail "mcpp new + run"; tail -15 run.log
fi

section "C. GUARD (index, #687): a fresh gcc@15.1.0 has no frozen header, and <mutex> compiles"
d=$root/c; mkdir -p "$d/src"; cd "$d"
printf '[package]\nname = "mtx"\nversion = "0.1.0"\n[toolchain]\nlinux = "gcc@15.1.0"\n' > mcpp.toml
printf '#include <memory>\n#include <mutex>\nint main() { std::mutex m; std::lock_guard g(m); return *std::make_unique<int>(0); }\n' > src/main.cpp
if timeout 2400 "$STORE" build > build.log 2>&1; then
    ok "gcc@15.1.0 compiles <mutex> and <memory> against glibc 2.44"
else
    fail "gcc@15.1.0 build"; grep -m3 -E 'error' build.log
fi
g15="$HOME/.mcpp/registry/data/xpkgs/xim-x-gcc/15.1.0"
if [ -d "$g15" ]; then
    frozen=$(grep -rlF 'auto-edited by fixincludes' "$g15"/lib/gcc/*/*/include-fixed 2>/dev/null | wc -l)
    [ "$frozen" -eq 0 ] && ok "the installed gcc@15.1.0 carries no fixincludes-frozen header" \
                        || fail "$frozen frozen header(s) remain in the installed gcc@15.1.0"
else
    fail "gcc@15.1.0 was not installed under $g15"
fi

section "D. CHANGE (#687): mcpp self doctor reports a frozen header in an installed gcc payload"
if [ -d "$g15" ]; then
    fx=$(ls -d "$g15"/lib/gcc/*/*/include-fixed | head -1)
    printf '/*  DO NOT EDIT THIS FILE.\n\n    It has been auto-edited by fixincludes from:\n\n\t"/verify/usr/include/probe.h"\n*/\n' > "$fx/verify-probe.h"
    "$STORE" self doctor > "$root/doctor.log" 2>&1
    if grep -q 'gcc@15.1.0' "$root/doctor.log" && grep -q 'verify-probe.h' "$root/doctor.log"; then
        ok "doctor names the payload and the frozen file"
    else
        fail "doctor did not report the planted frozen header"; grep -i -m3 'include-fixed\|fixincludes' "$root/doctor.log"
    fi
    rm -f "$fx/verify-probe.h"
    "$STORE" self doctor > "$root/doctor2.log" 2>&1
    grep -q 'verify-probe.h' "$root/doctor2.log" && fail "doctor still reports a removed file" \
                                                || ok "doctor is silent once the file is gone"
else
    skip "D: no gcc@15.1.0 payload (section C did not install it)"
fi

section "E. CHANGE (#685): the macOS deployment target reaches an aarch64-macos build from Linux"
d=$root/e; mkdir -p "$d/src"; cd "$d"
printf 'int main() { return 0; }\n' > src/main.cpp
cat > mcpp.toml <<EOF
[package]
name = "dt"
version = "0.1.0"
[build]
macos_deployment_target = "11.0"
[target.aarch64-macos]
toolchain = "llvm@$LLVM"
EOF
if timeout 2400 "$STORE" build --target aarch64-macos --configure-only > cfg.log 2>&1; then
    cdb=$(find target -name compile_commands.json | head -1)
    if [ -n "$cdb" ] && grep -q 'arm64-apple-macos11.0' "$cdb"; then
        ok "the manifest value reaches the triple (arm64-apple-macos11.0)"
    else
        fail "the triple does not carry 11.0"; grep -o -- '--target=[^ "]*' "$cdb" 2>/dev/null | sort -u
    fi
    MACOSX_DEPLOYMENT_TARGET=12.0 timeout 900 "$STORE" build --target aarch64-macos --configure-only > cfg2.log 2>&1
    cdb=$(ls -t $(find target -name compile_commands.json) | head -1)
    grep -q 'arm64-apple-macos12.0' "$cdb" && ok "MACOSX_DEPLOYMENT_TARGET overrides the manifest" \
                                           || fail "MACOSX_DEPLOYMENT_TARGET did not reach the triple"
else
    fail "configure for aarch64-macos"; tail -8 cfg.log
fi

section "F. CHANGE: xim: is the one toolchain namespace, and xim:msvc@system is not a spelling"
# Earlier releases stripped ANY `<ns>:` prefix, so `xim:gcc@16.1.0` already built
# and is a GUARD here; what changed is that another namespace is refused where it
# is read, and that `xim:msvc@system` is refused as a spelling (before, it failed
# later, on Linux as "only available on Windows hosts").
cd "$root/b/hello"
if timeout 1800 "$STORE" build --toolchain "xim:gcc@16.1.0" > xim.log 2>&1; then
    ok "GUARD: --toolchain xim:gcc@16.1.0 builds"
else
    fail "--toolchain xim:gcc@16.1.0"; tail -5 xim.log
fi
if "$STORE" build --toolchain "foo:gcc@16.1.0" > ximfoo.log 2>&1; then
    fail "foo:gcc@16.1.0 was accepted (the namespace was stripped)"
else
    grep -q 'is not a toolchain namespace' ximfoo.log && ok "foo:gcc@16.1.0 is refused as a namespace" \
                                                     || { fail "foo:gcc@16.1.0 refused for another reason"; head -3 ximfoo.log; }
fi
if "$STORE" build --toolchain "xim:msvc@system" > ximsys.log 2>&1; then
    fail "xim:msvc@system was accepted"
else
    grep -q 'xim:msvc@<version>' ximsys.log && ok "xim:msvc@system is refused as a spelling, naming both meanings" \
                                           || { fail "xim:msvc@system refused for another reason"; head -3 ximsys.log; }
fi

section "G. GUARD (mcpp-index): consumers of published packages build and pass their tests"
consumer() {  # name toolchain dep-table dep-line test-b64
    local name=$1 tc=$2 tbl=$3 dep=$4 b64=$5
    local d=$root/g-$name; mkdir -p "$d/tests" "$d/src"; cd "$d"
    printf 'int main() { return 0; }\n' > src/main.cpp
    { printf '[package]\nname = "%s"\nversion = "0.1.0"\n' "$name"
      [ -n "$tc" ] && printf '[toolchain]\nlinux = "%s"\n' "$tc"
      printf '[dependencies.%s]\n%s\n' "$tbl" "$dep"; } > mcpp.toml
    echo "$b64" | base64 -d > tests/t.cpp
    if timeout 3000 "$STORE" test > test.log 2>&1; then
        ok "$name: mcpp test passed${tc:+ ($tc)}"
    else
        fail "$name: mcpp test${tc:+ ($tc)}"; grep -m5 -E 'error|FAIL|failed' test.log
    fi
}
consumer yaml-cpp-gcc16 "" compat 'yaml-cpp = "0.9.0"' ""
consumer yaml-cpp-gcc15 "gcc@15.1.0" compat 'yaml-cpp = "0.9.0"' ""
consumer cli11 "" compat 'CLI11 = "2.7.2"' ""
consumer fmt "" fmtlib 'fmt = "12.2.0"' ""
consumer fmt-llvm "llvm@$LLVM" fmtlib 'fmt = "12.2.0"' ""

section "H. NOT RUN here"
skip "MSVC toolset selection (Windows only): e2e 760 and 239 in ci-windows-e2e / ci-windows-msvc-xlings"

printf '\n== summary ==\nfails=%d\n' "$fails"
[ -n "$skipped" ] && printf 'not run:%s\n' "$skipped"
[ "$fails" -eq 0 ]
